import { EmptyState, EmptyIcons } from '@components/ui/EmptyState';
import { SkeletonCard } from '@components/ui/Skeleton';
import { Link } from 'react-router-dom';
import { LayoutGrid, School, Anchor, Moon, Flame, Landmark } from 'lucide-react';
import { getForumBoards } from '../../services/forum.service';
import { useQuery } from '@tanstack/react-query';

const boardIconMap: Record<string, React.ElementType> = {
  lore: School,
  strategy: Anchor,
  creative: Moon,
  tavern: Flame,
  arkham_hall: Landmark,
};

export function ForumListPage() {
  const { data: boardsData, isLoading } = useQuery({
    queryKey: ['forumBoards'],
    queryFn: getForumBoards,
    staleTime: 5 * 60 * 1000,
  });
  const boards = boardsData?.boards || [];

  return (
    <div className="max-w-5xl mx-auto px-4 py-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div>
            <h1 className="text-2xl font-ritual font-bold" style={{ color: '#1a1a1a' }}>旧日低语</h1>
            <p className="text-sm mt-1" style={{ color: '#6b6558' }}>选择版块，进入你的讨论领域</p>
          </div>
          <div className="w-16 h-px" style={{ background: 'linear-gradient(90deg, rgba(201,162,39,0.4) 0%, transparent 100%)' }} />
        </div>
        <div className="hidden sm:flex items-center gap-2 text-[#6b6558] text-sm">
          <LayoutGrid size={16} />
          <span>共 {boards.length} 个版块</span>
        </div>
      </div>

      {/* Board Cards - 2x2 layout, longer cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
        {boards.map((b: any) => {
          const Icon = boardIconMap[b.key] || LayoutGrid;
          return (
            <Link
              key={b.key}
              to={`/forums/board/${b.key}`}
              className="group p-6 backdrop-blur-md bg-black/50 border border-[#3a3a3a]/40 rounded-lg min-h-[220px] flex flex-col justify-between shadow-lg shadow-black/40 hover:border-[#c9a227]/30 transition-all"
            >
              <div>
                <div className="flex items-start justify-between gap-3">
                  <div className="min-w-0">
                    <h2 className="text-xl font-bold group-hover:text-[#c9a227] transition-colors truncate text-[#e8d4a0]">
                      {b.name}
                    </h2>
                  </div>
                  <div className="flex flex-col items-end flex-shrink-0">
                    <span className="text-2xl font-bold text-[#e8d4a0]">{b.postCount}</span>
                    <span className="text-xs text-[#8b8375]">主题</span>
                  </div>
                </div>
                {b.description && (
                  <p className="text-sm text-[#b0a898] mt-3 leading-relaxed whitespace-pre-line">
                    {b.description}
                  </p>
                )}
              </div>

              <div className="mt-4 flex items-center justify-end">
                <Icon
                  size={32}
                  className="text-[#8b8375] group-hover:text-[#c9a227] transition-colors"
                />
              </div>
            </Link>
          );
        })}
      </div>

      {isLoading ? (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
          <SkeletonCard className="h-[220px]" />
          <SkeletonCard className="h-[220px]" />
          <SkeletonCard className="h-[220px]" />
          <SkeletonCard className="h-[220px]" />
        </div>
      ) : boards.length === 0 ? (
        <EmptyState
          icon={EmptyIcons.Clue}
          title="暂无可用版块"
          description="论坛版块尚未开放，敬请期待。"
          size="md"
          animate={false}
        />
      ) : null}
    </div>
  );
}
